update public.stories set title='قصة موسى عليه السلام',content='تتناول قصة موسى عليه السلام في القرآن مراحل متعددة من طفولته وبعثته إلى فرعون ومواجهة البحر. القيمة التربوية في القصة ليست أن الطريق يصبح سهلًا، بل أن الثبات على الحق يجتمع مع الأخذ بالأسباب واللجوء إلى الله. نلتزم في هذه المادة بما يثبته القرآن، ونفصل بين النص القرآني وبين التفاصيل القصصية التي قد تختلف رواياتها.',summary='الصبر والثبات',mood='الصبر والثبات',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://quran.com/20","https://quran.com/26"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='story-of-musa';
update public.stories set title='قصة يوسف عليه السلام',content='قصة يوسف عليه السلام تعرض سلسلة من الابتلاءات ثم التمكين، وتفتح أبوابًا للتأمل في الصبر وحسن التعامل مع الظلم وضبط الرغبات والعفو. لا نقدم تفاصيل درامية غير لازمة، بل نركز على البناء القرآني للقصة وما يمكن أن يتعلمه القارئ منه.',summary='الصبر والعفو',mood='الصبر والعفو',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://quran.com/12"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='story-of-yusuf';
update public.stories set title='قصة إبراهيم عليه السلام',content='تعرض قصة إبراهيم عليه السلام نموذجًا في طلب الحقيقة والثبات على التوحيد والطاعة عند الابتلاء. ويمكن للقارئ أن يقرأ المواقف في مواضعها القرآنية المختلفة بدل دمج الروايات في قصة واحدة لا تفرق بين الثابت والمشهور.',summary='التوحيد والثبات',mood='التوحيد والثبات',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://quran.com/2/124-132","https://quran.com/6/74-83"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='story-of-ibrahim';
update public.stories set title='أبو بكر الصديق رضي الله عنه',content='أبو بكر الصديق رضي الله عنه من كبار أصحاب النبي ﷺ وصاحبه في الهجرة ثم تولى الخلافة. يقدم الملف مدخلًا مختصرًا إلى سيرته مع التأكيد على الصدق والوفاء وتحمل المسؤولية، مع تجنب القصص الوعظية غير الموثقة.',summary='الصحبة والوفاء',mood='الصحبة والوفاء',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://sunnah.com/bukhari/1/1","https://sunnah.com/about"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='abu-bakr-siddiq';
update public.stories set title='عمر بن الخطاب رضي الله عنه',content='عمر بن الخطاب رضي الله عنه من كبار الصحابة والخلفاء الراشدين. دراسة سيرته تساعد على فهم معنى المسؤولية والمحاسبة وحسن إدارة الشأن العام، مع ضرورة التمييز بين الوقائع الثابتة والروايات التاريخية المختلفة.',summary='المسؤولية والعدل',mood='المسؤولية والعدل',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://sunnah.com/about"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='omar-ibn-khattab';
update public.stories set title='خالد بن الوليد رضي الله عنه',content='خالد بن الوليد رضي الله عنه من القادة المعروفين في عصر النبوة والخلافة الراشدة. القيمة التعليمية هنا في التخطيط والانضباط وتحمل المسؤولية، مع تجنب الأرقام والتفاصيل التي لا نملك لها توثيقًا واضحًا.',summary='التخطيط والانضباط',mood='التخطيط والانضباط',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://sunnah.com/about"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='khalid-ibn-walid';
update public.stories set title='الأندلس: حضارة وذاكرة',content='الأندلس ليست قصة ازدهار أو سقوط فقط؛ هي قرون من التحولات السياسية والعلمية والاجتماعية. يعرض هذا الملف منهجًا لقراءة التاريخ عبر الحكم والعمران والعلوم والعلاقات والصراعات، بدل اختزاله في صورة رومانسية.',summary='العلم والعمران',mood='العلم والعمران',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://www.britannica.com/place/Andalusia","https://en.wikipedia.org/wiki/History_of_al-Andalus"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":false}',updated_at=now() where slug='andalus-civilization';
update public.stories set title='غزوة بدر الكبرى',content='غزوة بدر من أبرز أحداث السيرة النبوية وورد ذكرها في القرآن. نعرض الحدث كدرس تاريخي وإيماني، ونفصل بين الوقائع التي تحتاج إلى مصدر تفصيلي وبين الدروس التربوية، مع تجنب الأرقام المتنازع عليها.',summary='الإيمان والصبر',mood='الإيمان والصبر',published=true,is_approved=true,metadata='{"editorial":true,"source_urls":["https://quran.com/8","https://sunnah.com/bukhari/64"],"reviewed_at":"2026-09-19T01:46:34.953Z","not_historical_claim":true}',updated_at=now() where slug='battle-of-badr-story';
