insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة','Our Lord, grant us good in this world and good in the Hereafter' ,'zikr-dua-quran-00201','ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار','Our Lord, grant us good in this world and good in the Hereafter.','للدعاء بخيري الدنيا والآخرة','القرآن الكريم، سورة البقرة 2:201','Quran 2:201','دعاء جامع لخيري الدنيا والآخرة','A comprehensive Quranic supplication.',true,'{"source_type":"quran","reference":"quran.com/2/201"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا لا تزغ قلوبنا بعد إذ هديتنا','Our Lord, do not let our hearts deviate after You have guided us' ,'zikr-dua-quran-00308','ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب','Our Lord, do not let our hearts deviate after You have guided us.','لطلب الثبات والهداية','القرآن الكريم، سورة آل عمران 3:8','Quran 3:8','طلب الثبات على الهدى','A supplication for steadfastness.',true,'{"source_type":"quran","reference":"quran.com/3/8"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('رب اشرح لي صدري','My Lord, expand my chest for me' ,'zikr-dua-quran-02025','رب اشرح لي صدري ويسر لي أمري واحلل عقدة من لساني يفقهوا قولي','My Lord, expand my chest for me and ease my task.','قبل التعلم أو الحديث في أمر مهم','القرآن الكريم، سورة طه 20:25-28','Quran 20:25-28','طلب التيسير والفهم وحسن البيان','For ease, understanding, and clear speech.',true,'{"source_type":"quran","reference":"quran.com/20/25-28"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('رب زدني علما','My Lord, increase me in knowledge' ,'zikr-dua-quran-20114','وقل رب زدني علما','My Lord, increase me in knowledge.','لطلب العلم النافع','القرآن الكريم، سورة طه 20:114','Quran 20:114','ربط التعلم بالدعاء','Connecting learning with supplication.',true,'{"source_type":"quran","reference":"quran.com/20/114"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('لا إله إلا أنت سبحانك إني كنت من الظالمين','There is no deity except You; glory be to You; I was among the wrongdoers' ,'zikr-dua-quran-21087','لا إله إلا أنت سبحانك إني كنت من الظالمين','There is no deity except You; glory be to You; I was among the wrongdoers.','عند الكرب والرجوع إلى الله','القرآن الكريم، سورة الأنبياء 21:87','Quran 21:87','إقرار بالتوحيد والافتقار إلى الله','Acknowledging Allah''s oneness and our need for Him.',true,'{"source_type":"quran","reference":"quran.com/21/87"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا ظلمنا أنفسنا','Our Lord, we have wronged ourselves' ,'zikr-dua-quran-00723','قالا ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين','Our Lord, we have wronged ourselves; if You do not forgive and have mercy on us, we will be among the losers.','للاعتراف بالخطأ وطلب المغفرة','القرآن الكريم، سورة الأعراف 7:23','Quran 7:23','تعليم الصراحة مع النفس والرجوع إلى الله','Encouraging honest repentance.',true,'{"source_type":"quran","reference":"quran.com/7/23"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا هب لنا من أزواجنا وذرياتنا قرة أعين','Our Lord, grant us comfort from our spouses and offspring' ,'zikr-dua-quran-25074','ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماما','Our Lord, grant us from our spouses and offspring comfort to our eyes.','لصلاح الأسرة والذرية','القرآن الكريم، سورة الفرقان 25:74','Quran 25:74','دعاء للأسرة والصلاح والقدوة','For family well-being and righteous example.',true,'{"source_type":"quran","reference":"quran.com/25/74"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا أفرغ علينا صبرا','Our Lord, pour upon us patience' ,'zikr-dua-quran-007126','ربنا أفرغ علينا صبرا وتوفنا مسلمين','Our Lord, pour upon us patience.','عند الشدة وطلب الثبات','القرآن الكريم، سورة الأعراف 7:126','Quran 7:126','طلب الصبر والثبات','For patience and steadfastness.',true,'{"source_type":"quran","reference":"quran.com/7/126"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا تقبل منا','Our Lord, accept from us' ,'zikr-dua-quran-20127','ربنا تقبل منا إنك أنت السميع العليم','Our Lord, accept from us; You are the All-Hearing, All-Knowing.','بعد العمل الصالح','القرآن الكريم، سورة البقرة 2:127','Quran 2:127','تذكير بأن القبول غاية لا مجرد الإنجاز','A reminder to seek acceptance.',true,'{"source_type":"quran","reference":"quran.com/2/127"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا','Our Lord, forgive our sins and our excess' ,'zikr-dua-quran-03147','ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا وثبت أقدامنا وانصرنا على القوم الكافرين','Our Lord, forgive our sins and our excess in our affairs, and make our feet firm.','لطلب المغفرة والثبات','القرآن الكريم، سورة آل عمران 3:147','Quran 3:147','جمع الاستغفار والثبات','For forgiveness and steadfastness.',true,'{"source_type":"quran","reference":"quran.com/3/147"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('رب أعوذ بك من همزات الشياطين','My Lord, I seek refuge in You from the incitements of devils' ,'zikr-dua-quran-23097','وقل رب أعوذ بك من همزات الشياطين وأعوذ بك رب أن يحضرون','My Lord, I seek refuge in You from the incitements of devils.','لطلب الحماية من الوساوس والإغواء','القرآن الكريم، سورة المؤمنون 23:97-98','Quran 23:97-98','تعليم الاستعاذة واللجوء إلى الله','Seeking refuge in Allah.',true,'{"source_type":"quran","reference":"quran.com/23/97-98"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('رب أدخلني مدخل صدق وأخرجني مخرج صدق','My Lord, admit me with a truthful entrance and bring me out with a truthful exit' ,'zikr-dua-quran-17080','وقل رب أدخلني مدخل صدق وأخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا','My Lord, admit me with a truthful entrance and bring me out with a truthful exit.','عند الانتقال بين المراحل والأعمال','القرآن الكريم، سورة الإسراء 17:80','Quran 17:80','طلب الصدق والتيسير والنصرة بالحق','For truthful transitions.',true,'{"source_type":"quran","reference":"quran.com/17/80"}')
insert into public.duas
(title_ar,title_en,slug,text_ar,text_en,occasion_ar,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values
('رب اغفر وارحم وأنت خير الراحمين','My Lord, forgive and have mercy; You are the best of the merciful' ,'zikr-dua-quran-23118','وقل رب اغفر وارحم وأنت خير الراحمين','My Lord, forgive and have mercy; You are the best of the merciful.','للمغفرة والرحمة','القرآن الكريم، سورة المؤمنون 23:118','Quran 23:118','دعاء جامع للمغفرة والرحمة','For forgiveness and mercy.',true,'{"source_type":"quran","reference":"quran.com/23/118"}')
